-- Version: V1.2 (2026-10-02) — data/samples/SkyTech_Leads_Sample100_import.sql — V1.2 (duplicate-safe)
-- 100-lead sample with SkyTech_BackOffice verification. SQL Server 2014 Developer (SSMS).
-- Run sql/01_create_skytechcrm.sql (V2.0+) first. SAFE TO RE-RUN: existing companies are updated, never duplicated.
USE SkyTechCRM;
GO
SET NOCOUNT ON;
DELETE FROM dbo.StgLeads;
EXEC dbo.usp_ImportStagedLeads @BatchName = N'Sample100 Oct-2026 RE+Utility BaltCity-BaltCo-Howard', @SourceFile = N'Overture Maps Places 2026-09-23.1';
GO
SELECT l.Status, COUNT(*) AS Leads FROM dbo.Leads l JOIN dbo.Companies c ON c.CompanyID = l.CompanyID WHERE c.SourceRecordID IS NOT NULL GROUP BY l.Status;
